## posthog_context
import {
  component$,
  createContextId,
  Slot,
  useContext,
  useContextProvider,
  useSignal,
  useVisibleTask$,
  type Signal,
} from "@builder.io/qwik";
import type posthog from "posthog-js";
import { useAuth } from "./auth-context";
import {
  FALLBACK_FEATURES,
  POSTHOG_FEATURE_FLAG_KEYS,
  setRuntimeFeatures,
  type FeatureFlags,
} from "./feature-flags";

interface FeatureFlagState {
  flags: FeatureFlags;
  loaded: boolean;
  configured: boolean;
  error?: string;
}

type PostHogClient = typeof posthog;

export const FeatureFlagContext = createContextId<Signal<FeatureFlagState>>(
  "twyne.feature-flags",
);

let clientPromise: Promise<PostHogClient | null> | null = null;
let initialized = false;

function posthogConfig(): {
  key: string;
  host: string;
  capture: boolean;
} | null {
  const key = import.meta.env.PUBLIC_POSTHOG_KEY as string | undefined;
  if (!key) return null;
  return {
    key,
    host:
      (import.meta.env.PUBLIC_POSTHOG_HOST as string | undefined) ??
      "https://us.i.posthog.com",
    capture: import.meta.env.PUBLIC_POSTHOG_CAPTURE !== "false",
  };
}

async function getPostHogClient(): Promise<PostHogClient | null> {
  if (typeof window === "undefined") return null;
  const config = posthogConfig();
  if (!config) return null;

  clientPromise ??= import("posthog-js").then((mod) => {
    const client = mod.default;
    if (!initialized) {
      client.init(config.key, {
        api_host: config.host,
        defaults: "2026-01-30",
        autocapture: config.capture,
        capture_pageview: config.capture,
        capture_pageleave: config.capture,
        disable_session_recording: !config.capture,
        opt_out_capturing_by_default: !config.capture,
        flag_keys: Object.values(POSTHOG_FEATURE_FLAG_KEYS),
      });
      initialized = true;
    }
    return client;
  });

  return clientPromise;
}

export async function capturePostHogEvent(
  event: string,
  properties: Record<string, unknown>,
): Promise<void> {
  const client = await getPostHogClient();
  if (!client) return;
  client.capture(event, properties);
}

function readFlags(client: PostHogClient): FeatureFlags {
  return {
    pricing:
      client.isFeatureEnabled(POSTHOG_FEATURE_FLAG_KEYS.pricing) ??
      FALLBACK_FEATURES.pricing,
    localAi:
      client.isFeatureEnabled(POSTHOG_FEATURE_FLAG_KEYS.localAi) ??
      FALLBACK_FEATURES.localAi,
  };
}

export function useFeatureFlags(): Signal<FeatureFlagState> {
  return useContext(FeatureFlagContext);
}

export const PostHogProvider = component$(() => {
  const flags = useSignal<FeatureFlagState>({
    flags: FALLBACK_FEATURES,
    loaded: !posthogConfig(),
    configured: !!posthogConfig(),
  });
  const auth = useAuth();

  useContextProvider(FeatureFlagContext, flags);

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ cleanup }) => {
    const client = await getPostHogClient();
    if (!client) {
      setRuntimeFeatures(FALLBACK_FEATURES);
      flags.value = {
        flags: FALLBACK_FEATURES,
        loaded: true,
        configured: false,
      };
      return;
    }

    const apply = (next: FeatureFlags, error?: string) => {
      setRuntimeFeatures(next);
      flags.value = {
        flags: next,
        loaded: true,
        configured: true,
        error,
      };
    };

    const unsubscribe = client.onFeatureFlags((_keys, _variants, meta) => {
      const next = meta?.errorsLoading ? FALLBACK_FEATURES : readFlags(client);
      apply(
        next,
        meta?.errorsLoading
          ? "PostHog feature flags failed to load"
          : undefined,
      );
    });

    const cached = readFlags(client);
    apply(cached);

    if (typeof unsubscribe === "function") {
      cleanup(unsubscribe);
    }
  });

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ track }) => {
    track(() => auth.value.user?.id);
    track(() => auth.value.loading);

    const client = await getPostHogClient();
    if (!client || auth.value.loading) return;

    if (auth.value.user) {
      client.identify(auth.value.user.id, {
        email: auth.value.user.email,
        name: auth.value.user.name,
        authProvider: auth.value.provider,
      });
    } else {
      client.reset();
    }
  });

  return <Slot />;
});

## auth_context
import {
  component$,
  createContextId,
  Slot,
  useContext,
  useContextProvider,
  useSignal,
  useVisibleTask$,
  type Signal,
} from "@builder.io/qwik";
import { authClient } from "./auth-client";
import { setConvexSyncContext, clearConvexSyncContext } from "./convex-sync";
import { useConvexClient } from "./convex-context";

export interface AuthUser {
  id: string;
  email: string;
  name?: string;
  image?: string;
}

export interface AuthState {
  user: AuthUser | null;
  loading: boolean;
  /** Restored ATProto identity, present alongside a Better Auth session. */
  atproto?: {
    did: string;
    handle: string;
    displayName?: string;
    avatar?: string;
  };
  /**
   * Which identity backs Convex. ATProto can coexist in `atproto`; it only
   * becomes the primary display identity when Better Auth is absent.
   */
  provider?: "convex" | "atproto";
}

export const AuthContext =
  createContextId<Signal<AuthState>>("twyne.auth-context");

export function useAuth(): Signal<AuthState> {
  return useContext(AuthContext);
}

export const AuthProvider = component$(() => {
  const authState = useSignal<AuthState>({ user: null, loading: true });
  const convexClient = useConvexClient();

  useContextProvider(AuthContext, authState);

  // eslint-disable-next-line qwik/no-use-visible-task
  useVisibleTask$(async ({ cleanup, track }) => {
    track(convexClient);

    // Restore/complete ATProto OAuth, but do not let it short-circuit Better
    // Auth. The two sessions serve different purposes and can coexist.
    const { initSession } = await import("./atproto");
    const atproto = await initSession();

    const sessionAtom = authClient.useSession;
    if (!sessionAtom || typeof sessionAtom !== "object") {
      authState.value = atproto
        ? {
            user: {
              id: atproto.did,
              email: atproto.handle,
              name: atproto.displayName ?? atproto.handle,
              image: atproto.avatar,
            },
            loading: false,
            provider: "atproto",
            atproto,
          }
        : { user: null, loading: false };
      clearConvexSyncContext();
      return;
    }

    async function syncFromAtom() {
      const val = sessionAtom.get?.() ?? sessionAtom;
      const sessionData = val?.data;

      if (sessionData?.user) {
        const user: AuthUser = {
          id: sessionData.user.id,
          email: sessionData.user.email ?? "",
          name: sessionData.user.name ?? undefined,
          image: sessionData.user.image ?? undefined,
        };
        if (convexClient.value) {
          try {
            const tokenResult = await (authClient as any).convex.token({
              fetchOptions: { throw: false },
            });
            const token = tokenResult?.data?.token as string | undefined;
            if (token) convexClient.value.setAuth(async () => token);
            else convexClient.value.setAuth(async () => null);
          } catch {
            convexClient.value.setAuth(async () => null);
          }
          setConvexSyncContext(convexClient.value, user.id);

          // This mutation requires the live Better Auth Convex token above.
          // ATProto proof still comes from the official legacy browser OAuth
          // client; see providerIdentity.ts for the server-conversion boundary.
          if (atproto) {
            try {
              const { linkNotOrganicDid } = await import(
                "./notorganic-provider"
              );
              await linkNotOrganicDid(convexClient.value, atproto.did);
            } catch (error) {
              console.warn("[twyne:notorganic] DID link failed", error);
            }
          }
        } else {
          clearConvexSyncContext();
        }
        authState.value = {
          user,
          loading: false,
          provider: "convex",
          atproto: atproto ?? undefined,
        };
      } else {
        authState.value = atproto
          ? {
              user: {
                id: atproto.did,
                email: atproto.handle,
                name: atproto.displayName ?? atproto.handle,
                image: atproto.avatar,
              },
              loading: val?.isPending ?? false,
              provider: "atproto",
              atproto,
            }
          : { user: null, loading: val?.isPending ?? false };
        try {
          convexClient.value?.setAuth(async () => null);
        } catch {
          // The client may not have installed an auth token yet.
        }
        clearConvexSyncContext();
      }
    }

    void syncFromAtom();

    if (typeof sessionAtom.subscribe === "function") {
      const unsub = sessionAtom.subscribe(() => {
        void syncFromAtom();
      });
      cleanup(() => {
        unsub();
        clearConvexSyncContext();
      });
    } else {
      cleanup(() => {
        clearConvexSyncContext();
      });
    }
  });

  return <Slot />;
});

