export async function runClientCustomCriterionJudge(
  req: {
    brief: ProjectBriefType | null;
    draftText: string;
    label: string;
    description: string;
  },
  settings: AiSettings,
): Promise<{ score: number; rationale: string; provider: string } | null> {
  const resolved = resolveFeatureConfig(settings, "rubric-judge");
